<style>
.hst{color:#25313C}.hst-head{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:20px}.hst-title{font-size:22px;font-weight:700;color:#123B5D}.hst-sub{font-size:13px;color:#64748B;margin-top:5px}.hst-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.hst-card{background:#fff;border:1px solid #CBD5E1;border-radius:14px;padding:18px;margin-bottom:16px}.hst-k{font-size:12px;color:#64748B;font-weight:600}.hst-v{font-size:26px;font-weight:700;color:#123B5D;margin-top:8px}.hst-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.hst-field label{display:block;font-size:12px;font-weight:600;margin-bottom:6px}.hst-input{width:100%;height:40px;border:1px solid #CBD5E1;border-radius:9px;padding:0 10px;background:#fff;font-size:13px}.hst-btn{display:inline-flex;padding:9px 13px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:#123B5D;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.hst-primary{background:#123B5D;color:#fff}.hst-table{width:100%;border-collapse:collapse;min-width:700px}.hst-table th{text-align:left;padding:12px;background:#F8FAFC;color:#64748B;font-size:11px}.hst-table td{padding:12px;border-bottom:1px solid #E2E8F0;font-size:13px}.hst-alert{padding:11px 14px;border-radius:9px;margin-bottom:14px;background:#F0FDF4;color:#166534;border:1px solid #BBF7D0;font-size:13px}.hst-error{color:#DC2626;font-size:12px}@media(max-width:850px){.hst-grid{grid-template-columns:repeat(2,1fr)}.hst-form{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.hst-grid,.hst-form{grid-template-columns:1fr}}
</style>